def parse_when(text):
    """Parse ISO 8601 text into an aware UTC datetime; raise ValueError if it is not a date."""
    when = datetime.fromisoformat(text)
    if when.tzinfo is None:
        # shortcut: text with no offset is read as UTC, reject it if callers need local time
        return when.replace(tzinfo=timezone.utc)
    return when.astimezone(timezone.utc)
EOF
