class ParseWhenTest(unittest.TestCase):
    def test_accepted_forms(self):
        utc = datetime(2026, 10, 1, 10, tzinfo=timezone.utc)
        self.assertEqual(parse_when("2026-10-01"), utc.replace(hour=0))
        self.assertEqual(parse_when("2026-10-01T10:00:00Z"), utc)
        self.assertEqual(parse_when("2026-10-01T12:00:00+02:00"), utc)
        self.assertEqual(parse_when("2026-10-01T12:00:00+02:00").utcoffset(), timedelta(0))

    def test_not_a_date(self):
        with self.assertRaises(ValueError):
            parse_when("tomorrow")
